"""Shared export pipeline for tabular row data.

Both public wrappers (csv_exporter.export_csv and json_exporter.export_json)
delegate to export_rows so normalization and serialization live in one place.
"""

import csv
import io
import json

_FIELDS = ("id", "name")


def _normalize(rows):
    """Yield (csv_cell_list, json_dict) pairs for each row.

    Consumes ``rows`` exactly once (supporting one-shot iterables) and never
    mutates it. Only ``id`` and ``name`` are kept; missing or None values
    become '' and everything else is stringified. Input order is preserved.
    """
    for row in rows:
        cells = ["" if row.get(key) is None else str(row[key]) for key in _FIELDS]
        yield cells, dict(zip(_FIELDS, cells))


def _serialize_csv(rows):
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(_FIELDS)
    for cells, _ in _normalize(rows):
        writer.writerow(cells)
    return buffer.getvalue()


def _serialize_json(rows):
    clean = [record for _, record in _normalize(rows)]
    return json.dumps(clean, ensure_ascii=False, separators=(",", ":"))


_SERIALIZERS = {
    "csv": _serialize_csv,
    "json": _serialize_json,
}


def export_rows(rows, format):
    """Export rows in the requested format ('csv' or 'json').

    Raises ValueError for unsupported formats.
    """
    serializer = _SERIALIZERS.get(format)
    if serializer is None:
        raise ValueError("unsupported format")
    return serializer(rows)

